// Known-answer tests against the asn1tools vectors in test-vectors/<codec>/, through TypeScript generated by
// `asn1 generate-typescript` (run `npm run generate` first). The checks mirror the .NET interoperability tests:
// exact encodings, decoding to the expected value, our own round trip, and the same documented deviations of
// asn1tools from the ITU-T texts.

import assert from 'node:assert/strict';
import { readdirSync, readFileSync } from 'node:fs';
import { dirname, join, resolve as resolvePath } from 'node:path';
import { describe, it } from 'node:test';
import { fileURLToPath, pathToFileURL } from 'node:url';
import * as rt from '@dotasn/runtime';
import type { EncodingRule } from '@dotasn/wasm';

const here = dirname(fileURLToPath(import.meta.url));
const root = resolvePath(here, '../../..');

interface Vector {
  type: string;
  value: unknown;
  hex: string;
  decoded?: unknown;
}

/** The rules under test. */
export interface RuleSet {
  readonly ber: EncodingRule;
  readonly der: EncodingRule;
  readonly uper: EncodingRule;
  readonly aper: EncodingRule;
  readonly oer: EncodingRule;
  readonly coer: EncodingRule;
  readonly jer: EncodingRule;
}

interface Suite {
  /** Directory under test-vectors/. */
  codec: string;
  label: string;
  rule: keyof RuleSet;
  /** Whether our encoding must equal asn1tools' byte for byte (otherwise only values are compared). */
  exact: boolean;
  /** For canonical rules: the lenient rule that decodes asn1tools' unsorted SET/SET OF encodings. */
  lenient?: keyof RuleSet;
}

const suites: Suite[] = [
  { codec: 'ber', label: 'BER', rule: 'ber', exact: false },
  { codec: 'der', label: 'DER', rule: 'der', exact: true, lenient: 'ber' },
  { codec: 'uper', label: 'UPER', rule: 'uper', exact: true },
  { codec: 'per', label: 'APER', rule: 'aper', exact: true },
  { codec: 'oer', label: 'OER', rule: 'oer', exact: true },
  { codec: 'oer', label: 'COER', rule: 'coer', exact: true, lenient: 'oer' },
  { codec: 'jer', label: 'JER', rule: 'jer', exact: false },
];

// Documented deviations of asn1tools from the standards, shared with the .NET tests; checked by round trip.
const deviations = (JSON.parse(readFileSync(join(root, 'test-vectors', 'deviations.json'), 'utf8')) as {
  deviations: { codec: string; file: string; type: string }[];
}).deviations.map(d => [d.codec, d.file, d.type] as const);

const isDeviation = (codec: string, file: string, type: string): boolean =>
  deviations.some(([c, f, t]) => c === codec && f === file && (t === '*' || t === type));

/** The descriptors exported by the generated modules of a case set, by qualified ASN.1 name. */
async function descriptors(caseSet: string): Promise<Map<string, rt.Asn1Type>> {
  const dir = join(here, 'generated', caseSet);
  const map = new Map<string, rt.Asn1Type>();
  for (const file of readdirSync(dir).filter(f => f.endsWith('.ts'))) {
    const mod = (await import(pathToFileURL(join(dir, file)).href)) as Record<string, unknown>;
    for (const value of Object.values(mod)) {
      if (typeof value === 'object' && value !== null && 'kind' in value) {
        const d = rt.resolve(value as rt.Asn1Type);
        map.set(d.name, value as rt.Asn1Type);
      }
    }
  }

  return map;
}

/** JSON with sorted keys, for comparing values regardless of member order. */
function canonical(v: unknown): string {
  if (Array.isArray(v)) {
    return `[${v.map(canonical).join(',')}]`;
  }

  if (typeof v === 'object' && v !== null) {
    return `{${Object.keys(v).sort().map(k => `${JSON.stringify(k)}:${canonical((v as Record<string, unknown>)[k])}`).join(',')}}`;
  }

  return JSON.stringify(v);
}

/** True if two hexadecimal UTF-8 JSON texts hold the same JSON value. */
function sameJson(hexA: string, hexB: string): boolean {
  const parse = (hex: string): string => canonical(JSON.parse(new TextDecoder().decode(rt.fromHex(hex))));
  try {
    return parse(hexA) === parse(hexB);
  } catch {
    return false;
  }
}

const isPer = (rule: EncodingRule): boolean => rule.name === 'UPER' || rule.name === 'APER';

/** True if a type (transitively) contains SET or SET OF (canonical orders that asn1tools does not apply). */
function containsSet(t: rt.Descriptor, seen = new Set<object>()): boolean {
  if (seen.has(t)) {
    return false;
  }

  seen.add(t);
  switch (t.kind) {
    case 'set':
    case 'setOf':
      return true;
    case 'sequence':
      return t.components.some(c => containsSet(rt.typeOf(c), seen));
    case 'choice':
      return t.alternatives.some(a => containsSet(rt.typeOf(a), seen));
    case 'sequenceOf':
      return containsSet(rt.elementOf(t), seen);
    default:
      return false;
  }
}

const hexOf = (bytes: Uint8Array): string => rt.toHex(bytes);

/** The directory of the TypeScript generated for a case set (with dotasn-schema.ts). */
export const generatedDir = (caseSet: string): string => join(here, 'generated', caseSet);

/** Defines one test per vector file and rule, with the rules that `rulesFor` returns for each case set. */
export function defineVectorSuites(rulesFor: (caseSet: string) => Promise<RuleSet>): void {
  for (const suite of suites) {
    const { codec } = suite;
    const dir = join(root, 'test-vectors', codec);
    describe(`${suite.label} vectors`, () => {
      for (const file of readdirSync(dir).filter(f => f.endsWith('.json')).sort()) {
        const name = file.replace(/\.json$/, '');
        it(name, async t => {
          const vectors = (JSON.parse(readFileSync(join(dir, file), 'utf8')) as { cases: Vector[] }).cases;
          if (vectors.length === 0) {
            t.skip('no vectors');
            return;
          }

          const types = await descriptors(name);
          const rules = await rulesFor(name);
          const rule = rules[suite.rule];
          const lenient = suite.lenient === undefined ? undefined : rules[suite.lenient];
          const failures: string[] = [];
          let exact = 0;
          for (const v of vectors) {
            const type = types.get(v.type);
            if (!type) {
              failures.push(`${v.type}: no generated descriptor`);
              continue;
            }

            try {
              const value = rt.fromNotation(type, v.value);
              if (isDeviation(codec, name, v.type)) {
                // Not comparable with the reference; our own encoding must still round-trip.
                const ours = hexOf(rule.encode(type, value));
                const again = hexOf(rule.encode(type, rule.decode(type, rt.fromHex(ours))));
                if (again !== ours) {
                  failures.push(`${v.type}: round trip changed ${ours} into ${again}`);
                }

                continue;
              }

              if (lenient && containsSet(rt.resolve(type))) {
                // asn1tools leaves SET/SET OF in textual order: compare the canonical encodings of both values, and
                // require that ours is accepted by the strict decoder.
                const theirs = hexOf(rule.encode(type, lenient.decode(type, rt.fromHex(v.hex))));
                const ours = rule.encode(type, value);
                rule.decode(type, ours);
                if (theirs !== hexOf(ours)) {
                  failures.push(`${v.type}: canonical ${suite.label} differs: ${theirs} vs ${hexOf(ours)}`);
                }

                continue;
              }

              const encoded = hexOf(rule.encode(type, value));
              if (v.hex === '' && isPer(rule)) {
                // X.691 11.1.3: a value of no bits is one zero octet by default; asn1tools sends no octets, which the
                // emptyPerEncodingAsZeroOctet option reproduces.
                const none = hexOf(rule.encode(type, value, { emptyPerEncodingAsZeroOctet: false }));
                if (encoded !== '00' || none !== '') {
                  failures.push(`${v.type}: empty PER encoding ${encoded} (default) and '${none}' (without the zero octet)`);
                  continue;
                }

                exact++;
              } else if (encoded === v.hex || (rule.name === 'JER' && sameJson(encoded, v.hex))) {
                // JER: white space, escapes and member order are sender's options (X.697 27.3.3, 7.6.3).
                exact++;
              } else if (suite.exact) {
                failures.push(`${v.type} ${JSON.stringify(v.value).slice(0, 200)}: encoded ${encoded}, expected ${v.hex}`);
                continue;
              }

              // Decode the reference encoding and compare with asn1tools' own decoding.
              // Our decoding must equal asn1tools' own decoding (which adds DEFAULT values) or the original value
              // (asn1tools decodes some values wrongly, e.g. OBJECT IDENTIFIER 2.x with x >= 40, X.690 8.19.4).
              // Empty PER input is decoded as it is (DotAsn 0.1.1 accepts it).
              const decoded = canonical(rt.toNotation(type, rule.decode(type, rt.fromHex(v.hex))));
              const expected = decoded === canonical(v.value) ? decoded : canonical(v.decoded ?? v.value);
              if (decoded !== expected) {
                failures.push(`${v.type}: decoded ${decoded.slice(0, 300)}, expected ${expected.slice(0, 300)}`);
                continue;
              }

              // Our own encoding must decode to the same value.
              const roundTrip = canonical(rt.toNotation(type, rule.decode(type, rt.fromHex(encoded))));
              if (roundTrip !== expected) {
                failures.push(`${v.type}: round trip ${roundTrip.slice(0, 300)}, expected ${expected.slice(0, 300)}`);
              }
            } catch (e) {
              failures.push(`${v.type} ${JSON.stringify(v.value).slice(0, 200)}: ${(e as Error).message}`);
            }
          }

          t.diagnostic(`${exact}/${vectors.length} exact`);
          assert.equal(failures.length, 0, `${failures.length}/${vectors.length} failed (${exact} exact):\n${failures.slice(0, Number(process.env.VECTOR_FAILURES ?? 8)).join('\n')}`);
        });
      }
    });
  }
}
